export interface ConnectorConfig {
  /** Brevo API key with permissions to create contacts and manage lists. */
  brevoApiKey: string
  /** The Brevo contact list ID to subscribe the contact to. */
  brevoListId: number
  /** Optional injected fetch for testing. */
  fetch?: typeof fetch
}

export interface TypeformWebhookPayload {
  event_id: string
  event_type: string
  form_response: {
    form_id: string
    token: string
    submitted_at: string
    answers: Array<{
      type: string
      email?: string
      text?: string
      field: {
        id: string
        type: string
      }
    }>
    hidden: Record<string, unknown>
  }
}

export interface BrevoContactResponse {
  id: number
}

export interface HandleResult {
  brevoContactId: number
}

function extractEmail(answers: TypeformWebhookPayload['form_response']['answers']): string | undefined {
  const emailAnswer = answers.find((a) => a.field.type === 'email' && a.email)
  return emailAnswer?.email
}

function extractShortTextAnswers(answers: TypeformWebhookPayload['form_response']['answers']): string[] {
  return answers
    .filter((a) => a.field.type === 'short_text' && typeof a.text === 'string')
    .map((a) => a.text)
}

export async function handle(
  payload: TypeformWebhookPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  if (!payload?.form_response) {
    throw new Error('Missing required field: form_response')
  }
  if (!payload.form_response.token) {
    throw new Error('Missing required field: form_response.token')
  }
  if (!payload.form_response.answers || !Array.isArray(payload.form_response.answers)) {
    throw new Error('Missing required field: form_response.answers')
  }

  const email = extractEmail(payload.form_response.answers)
  if (!email) {
    throw new Error('Missing required field: email (no answer with field.type === "email")')
  }

  const shortTexts = extractShortTextAnswers(payload.form_response.answers)
  const firstName = shortTexts[0] ?? ''
  const lastName = shortTexts[1] ?? ''
  const externalId = payload.form_response.token

  const brevoPayload = {
    email,
    attributes: {
      FNAME: firstName,
      LNAME: lastName,
    },
    listIds: [config.brevoListId],
    updateEnabled: true,
  }

  const fetchImpl = config.fetch ?? fetch
  const url = 'https://api.brevo.com/v3/contacts'
  const headers: Record<string, string> = {
    'api-key': config.brevoApiKey,
    'Content-Type': 'application/json',
    Accept: 'application/json',
  }

  const maxRetries = 3
  let lastError: Error | undefined

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    const response = await fetchImpl(url, {
      method: 'POST',
      headers,
      body: JSON.stringify(brevoPayload),
    })

    if (response.status >= 200 && response.status < 300) {
      const data = (await response.json()) as BrevoContactResponse
      return { brevoContactId: data.id }
    }

    if (response.status === 429 || (response.status >= 500 && response.status < 600)) {
      const retryAfter = response.headers.get('retry-after')
      let delayMs: number
      if (retryAfter) {
        const asSeconds = Number(retryAfter)
        if (!Number.isNaN(asSeconds)) {
          delayMs = asSeconds * 1000
        } else {
          const date = new Date(retryAfter)
          delayMs = Number.isNaN(date.getTime()) ? 0 : date.getTime() - Date.now()
        }
      } else {
        delayMs = 0
      }
      const baseMs = 1000
      const exponentialMs = baseMs * 2 ** attempt
      const finalDelay = Math.max(delayMs, exponentialMs)
      if (finalDelay > 0 && attempt < maxRetries) {
        await new Promise((resolve) => setTimeout(resolve, finalDelay))
      }
      lastError = new Error(`Brevo API returned ${response.status} at ${url}`)
      continue
    }

    const text = await response.text().catch(() => '')
    throw new Error(`Brevo API error ${response.status} at ${url}: ${text}`)
  }

  throw lastError ?? new Error(`Brevo API failed after ${maxRetries + 1} attempts at ${url}`)
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, TypeformWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      brevoApiKey: 'test-api-key',
      brevoListId: 123,
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as TypeformWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.brevoContactId).toBe(456)
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig
  let calls: RecordedCall[]

  beforeEach(() => {
    const { fetch, calls: recordedCalls } = fakeFetch((req) => {
      if (req.url === 'https://api.brevo.com/v3/contacts' && req.method === 'POST') {
        return jsonResponse({ id: 456 }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })
    calls = recordedCalls
    baseConfig = {
      brevoApiKey: 'test-api-key',
      brevoListId: 123,
      fetch,
    }
  })

  it('maps fields correctly and calls Brevo with expected payload', async () => {
    const payload: TypeformWebhookPayload = {
      event_id: 'evt1',
      event_type: 'form_response',
      form_response: {
        form_id: 'f1',
        token: 'resp-123',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'test@example.com', field: { id: 'e1', type: 'email' } },
          { type: 'text', text: 'John', field: { id: 'f1', type: 'short_text' } },
          { type: 'text', text: 'Doe', field: { id: 'f2', type: 'short_text' } },
        ],
        hidden: {},
      },
    }

    const result = await handle(payload, baseConfig)

    expect(result.brevoContactId).toBe(456)
    expect(calls).toHaveLength(1)
    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toBe('https://api.brevo.com/v3/contacts')
    expect(call.headers.get('api-key')).toBe('test-api-key')
    expect(call.json).toEqual({
      email: 'test@example.com',
      attributes: { FNAME: 'John', LNAME: 'Doe' },
      listIds: [123],
      updateEnabled: true,
    })
  })

  it('uses empty strings when first/last name are missing', async () => {
    const payload: TypeformWebhookPayload = {
      event_id: 'evt2',
      event_type: 'form_response',
      form_response: {
        form_id: 'f1',
        token: 'resp-456',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'jane@example.com', field: { id: 'e1', type: 'email' } },
        ],
        hidden: {},
      },
    }

    const result = await handle(payload, baseConfig)

    expect(result.brevoContactId).toBe(456)
    expect(calls[0].json).toEqual({
      email: 'jane@example.com',
      attributes: { FNAME: '', LNAME: '' },
      listIds: [123],
      updateEnabled: true,
    })
  })

  it('throws when email is missing', async () => {
    const payload: TypeformWebhookPayload = {
      event_id: 'evt3',
      event_type: 'form_response',
      form_response: {
        form_id: 'f1',
        token: 'resp-789',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'text', text: 'John', field: { id: 'f1', type: 'short_text' } },
        ],
        hidden: {},
      },
    }

    await expect(handle(payload, baseConfig)).rejects.toThrow(
      'Missing required field: email (no answer with field.type === "email")',
    )
  })

  it('throws when form_response.token is missing', async () => {
    const payload = {
      event_id: 'evt4',
      event_type: 'form_response',
      form_response: {
        form_id: 'f1',
        token: '',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'test@example.com', field: { id: 'e1', type: 'email' } },
        ],
        hidden: {},
      },
    } as unknown as TypeformWebhookPayload

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: form_response.token')
  })

  it('throws when form_response.answers is missing', async () => {
    const payload = {
      event_id: 'evt5',
      event_type: 'form_response',
      form_response: {
        form_id: 'f1',
        token: 'resp-111',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: undefined,
        hidden: {},
      },
    } as unknown as TypeformWebhookPayload

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing required field: form_response.answers')
  })

  it('throws on non-2xx response with status and endpoint', async () => {
    const { fetch, calls: errorCalls } = fakeFetch(() => jsonResponse({ error: 'unauthorized' }, 401))
    const config: ConnectorConfig = { ...baseConfig, fetch }

    const payload: TypeformWebhookPayload = {
      event_id: 'evt6',
      event_type: 'form_response',
      form_response: {
        form_id: 'f1',
        token: 'resp-222',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'test@example.com', field: { id: 'e1', type: 'email' } },
        ],
        hidden: {},
      },
    }

    await expect(handle(payload, config)).rejects.toThrow(
      'Brevo API error 401 at https://api.brevo.com/v3/contacts',
    )
    expect(errorCalls).toHaveLength(1)
  })

  it('retries on 429 and succeeds on second attempt', async () => {
    let attempt = 0
    const { fetch, calls: retryCalls } = fakeFetch((req) => {
      attempt++
      if (attempt === 1) {
        return jsonResponse({ error: 'rate limited' }, 429)
      }
      return jsonResponse({ id: 789 }, 201)
    })
    const config: ConnectorConfig = { ...baseConfig, fetch }

    const payload: TypeformWebhookPayload = {
      event_id: 'evt7',
      event_type: 'form_response',
      form_response: {
        form_id: 'f1',
        token: 'resp-333',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'retry@example.com', field: { id: 'e1', type: 'email' } },
        ],
        hidden: {},
      },
    }

    const result = await handle(payload, config)

    expect(result.brevoContactId).toBe(789)
    expect(retryCalls).toHaveLength(2)
  })

  it('retries on 500 and exhausts retries', async () => {
    const { fetch, calls: exhaustCalls } = fakeFetch(() => jsonResponse({ error: 'server error' }, 500))
    const config: ConnectorConfig = { ...baseConfig, fetch }

    const payload: TypeformWebhookPayload = {
      event_id: 'evt8',
      event_type: 'form_response',
      form_response: {
        form_id: 'f1',
        token: 'resp-444',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'exhaust@example.com', field: { id: 'e1', type: 'email' } },
        ],
        hidden: {},
      },
    }

    await expect(handle(payload, config)).rejects.toThrow(
      'Brevo API failed after 4 attempts at https://api.brevo.com/v3/contacts',
    )
    expect(exhaustCalls).toHaveLength(4)
  })

  it('respects Retry-After header in seconds', async () => {
    let attempt = 0
    const { fetch, calls: raCalls } = fakeFetch((req) => {
      attempt++
      if (attempt === 1) {
        const res = jsonResponse({ error: 'rate limited' }, 429)
        res.headers.set('retry-after', '1')
        return res
      }
      return jsonResponse({ id: 999 }, 201)
    })
    const config: ConnectorConfig = { ...baseConfig, fetch }

    const payload: TypeformWebhookPayload = {
      event_id: 'evt9',
      event_type: 'form_response',
      form_response: {
        form_id: 'f1',
        token: 'resp-555',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'retryafter@example.com', field: { id: 'e1', type: 'email' } },
        ],
        hidden: {},
      },
    }

    const result = await handle(payload, config)

    expect(result.brevoContactId).toBe(999)
    expect(raCalls).toHaveLength(2)
  })

  it('respects Retry-After header as HTTP date', async () => {
    let attempt = 0
    const futureDate = new Date(Date.now() + 500).toUTCString()
    const { fetch, calls: raDateCalls } = fakeFetch((req) => {
      attempt++
      if (attempt === 1) {
        const res = jsonResponse({ error: 'rate limited' }, 429)
        res.headers.set('retry-after', futureDate)
        return res
      }
      return jsonResponse({ id: 888 }, 201)
    })
    const config: ConnectorConfig = { ...baseConfig, fetch }

    const payload: TypeformWebhookPayload = {
      event_id: 'evt10',
      event_type: 'form_response',
      form_response: {
        form_id: 'f1',
        token: 'resp-666',
        submitted_at: '2024-01-01T00:00:00Z',
        answers: [
          { type: 'email', email: 'retrydate@example.com', field: { id: 'e1', type: 'email' } },
        ],
        hidden: {},
      },
    }

    const result = await handle(payload, config)

    expect(result.brevoContactId).toBe(888)
    expect(raDateCalls).toHaveLength(2)
  })
})

